6. var builder = WebApplication.CreateBuilder(args);
7. 
8. var mlContext = new MLContext(seed: 42);
9. 
10. var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
11. var data = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
12. 
13. var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);
14. 
15. var pipeline = mlContext.Transforms.Conversion.MapValue("Label",
16.         new[] { new KeyValuePair<string, bool>("Yes", true), new KeyValuePair<string, bool>("No", false) },
17.         "Churned")
18.     .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", "Region"))
19.     .Append(mlContext.Transforms.Concatenate("Features", "Age", "Income", "RegionEncoded", "PurchaseHistory"))
20.     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
21.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());
22. 
23. var model = pipeline.Fit(split.TrainSet);
24. 
25. var predictions = model.Transform(split.TestSet);
26. var metrics = mlContext.BinaryClassification.Evaluate(predictions);
27. Console.WriteLine($"AUC: {metrics.AreaUnderRocCurve:F4}, F1: {metrics.F1Score:F4}, Accuracy: {metrics.Accuracy:F4}");
28. 
29. var modelPath = Path.Combine(AppContext.BaseDirectory, "churn_model.zip");
30. mlContext.Model.Save(model, data.Schema, modelPath);
31. 
32. builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
33.     .FromFile(modelPath);
34. 
35. var app = builder.Build();
36. 
37. app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerData customer) =>
38. {
39.     var prediction = pool.Predict(customer);
40.     return Results.Ok(new
41.     {
42.         WillChurn = prediction.PredictedLabel,
43.         prediction.Probability,
44.         prediction.Score
45.     });
46. });
47. 
48. app.MapGet("/metrics", () => Results.Ok(new
49. {
50.     metrics.Accuracy,
51.     metrics.AreaUnderRocCurve,
52.     metrics.F1Score
53. }));
54. 
55. app.MapGet("/", () => "ChurnPredictor API is running");
56. 
57. app.Run();
58.

